# CMap format: beginbfchar <src> <dst> endbfchar, beginbfrange <a> <b> <dst> endbfrange
def parse_cmap(t):
    out = {}
    for m in re.finditer(rb'beginbfchar(.*?)endbfchar', t, re.S):
        for a, b in re.findall(rb'<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>', m.group(1)):
            src = bytes.fromhex(a.decode())
            dst = bytes.fromhex(b.decode()).decode('utf-16-be', 'replace')
            out[src] = dst
    for m in re.finditer(rb'beginbfrange(.*?)endbfrange', t, re.S):
        for a, b, c in re.findall(rb'<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>', m.group(1)):
            start = int(a, 16); end = int(b, 16); dst = int(c, 16)
            for i, code in enumerate(range(start, end+1)):
                out[code.to_bytes(2,'big')] = chr(dst+i)
    return out

cmaps = [parse_cmap(t) for t in streams if b'beginbfchar' in t or b'beginbfrange' in t]
print("num cmaps:", len(cmaps))
# merge: use first cmap that has the code
merged = {}
for c in cmaps:
    for k,v in c.items():
        merged.setdefault(k, v)

def decode_hex(h):
    raw = bytes.fromhex(h)
    res = []
    i = 0
    while i < len(raw):
        for L in (2,1):
            if i+L <= len(raw) and raw[i:i+L] in merged:
                res.append(merged[raw[i:i+L]]); i += L; break
        else:
            res.append('?'); i += 1
    return ''.join(res)

def decode_lit(s):
    # literal PDF string, decode bytes
    res = []
    i = 0
    while i < len(s):
        if s[i:i+1] == b'\\':
            # simple escape
            c = s[i+1:i+2]
            if c in b'nrtbf()\\':
                res.append({b'n':'\n',b'r':'\r',b't':'\t',b'b':'\b',b'f':'\f',b'(':'(',b')':')',b'\\':'\\'}[c])
