                j = i+1; oc = b''
                while j < len(s) and s[j:j+1].isdigit() and len(oc) < 3:
                    oc += s[j:j+1]; j += 1
                res.append(chr(int(oc, 8)))
                i = j; continue
            else:
                res.append(c.decode('latin-1'))
            i += 2; continue
        for L in (2,1):
            if i+L <= len(s) and s[i:i+L] in merged:
                res.append(merged[s[i:i+L]]); i += L; break
        else:
            res.append('?'); i += 1
    return ''.join(res)

# Process content streams: lines of text with Tj and TJ
out_lines = []
for t in streams:
    if b'Tj' not in t and b'TJ' not in t:
        continue
    # split into lines by '1 0 0 1 x y Tm' or Td moves: simpler: track Tm/Td y position
    # iterate operators in order
    tokens = re.findall(rb'\[(?:[^\[\]]*)\]\s*TJ|\((?:[^()\\]|\\.)*\)\s*Tj|([0-9.\-]+)\s+([0-9.\-]+)\s+Td|1\s+0\s+0\s+1\s+([0-9.\-]+)\s+([0-9.\-]+)\s+Tm', t)
    # Simpler approach: regex finditer over the stream preserving order
    pos_y = None
    for m in re.finditer(rb'1\s+0\s+0\s+1\s+([0-9.\-]+)\s+([0-9.\-]+)\s+Tm|\((?:[^()\\]|\\.)*\)\s*Tj|\[(?:[^[\]]*)\]\s*TJ', t):
        g = m.group(0)
        if b'Tm' in g:
            y = float(m.group(2))
            if pos_y is None or abs(y - pos_y) > 1:
                out_lines.append('')
            pos_y = y
        elif b'Tj' in g:
            lit = g[1:g.rfind(b')')]
            out_lines[-1] += decode_lit(lit) if out_lines else decode_lit(lit)
        elif b'TJ' in g:
            s = g[1:g.rfind(b']')]
            for lit in re.findall(rb'\((?:[^()\\]|\\.)*\)', s):
                out_lines[-1] += decode_lit(lit[1:-1])
    if not out_lines:
        continue

for ln in out_lines:
    print(ln.rstrip())
